const root=document.querySelector('#app');
const toastNode=document.querySelector('#toast');
const state={token:sessionStorage.getItem('sx_token')||'',user:sessionStorage.getItem('sx_user')||'',admin:sessionStorage.getItem('sx_admin')==='true',page:location.hash.slice(1)||'home',owner:sessionStorage.getItem('sx_admin')==='true'?(sessionStorage.getItem('sx_owner')||''):'',assets:[],expiry:[],accounts:[],configs:[],tokens:[],accountRegistrationEnabled:true,assetScope:'CURRENT',assetStatus:'ALL',assetSort:'purchase_date',expiryStatus:'ALL',expiryBucket:'ALL',expirySort:'actual_expiry_date',query:'',busy:false,loadError:'',loadedPages:new Set(),renderedPageKey:''};
const esc=(v='')=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=c=>new Intl.NumberFormat('zh-CN',{style:'currency',currency:'CNY'}).format((Number(c)||0)/100);
const date=v=>v?new Date(`${v.slice(0,10)}T00:00:00`).toLocaleDateString('zh-CN',{year:'numeric',month:'2-digit',day:'2-digit'}):'—';
const api=async(path,opts={})=>{const headers=new Headers(opts.headers||{});if(state.token)headers.set('Authorization',`Bearer ${state.token}`);if(opts.body!==undefined)headers.set('Content-Type','application/json');const r=await fetch(path,{...opts,headers,body:opts.body===undefined?undefined:JSON.stringify(opts.body)});const type=r.headers.get('content-type')||'';const data=type.includes('json')?await r.json():await r.text();if(!r.ok){const e=new Error(data?.error||data?.message||`请求失败 (${r.status})`);e.status=r.status;e.data=data;throw e}return data};
const key=()=>crypto.randomUUID();
function notify(message){toastNode.textContent=message;toastNode.classList.add('show');clearTimeout(notify.timer);notify.timer=setTimeout(()=>toastNode.classList.remove('show'),2800)}
function logout(){state.token='';state.user='';state.admin=false;state.owner='';state.loadError='';state.loadedPages.clear();state.renderedPageKey='';sessionStorage.clear();location.hash='login';render()}
function navItem(id,label,icon){return `<button data-page="${id}" class="${state.page===id?'active':''}"><span class="nav-icon">${icon}</span>${label}</button>`}
function frame(title,body,sub=''){const name=state.user||'账户';root.innerHTML=`<div class="shell"><aside class="sidebar"><div class="brand"><span class="brand-mark">燧</span><span>燧人<small>SUIRENX · WEB</small></span></div><div class="nav-label">工作区</div><nav class="nav">${navItem('home','总览','◫')}${navItem('assets','资产','▣')}${navItem('expiry','用品期限','◇')}${navItem('conflicts','版本冲突','△')}</nav>${state.admin?`<div class="nav-label">受限管理</div><nav class="nav">${navItem('accounts','账号与数据','♙')}${navItem('configs','配置文件','⌁')}${navItem('tokens','API token','⌑')}</nav>`:''}<div class="side-note">本机记录仍是事实来源。同步为可选边界，不会替代本机备份或提醒设置。</div><div class="profile"><span class="avatar">${esc(name.slice(0,1).toUpperCase())}</span><span class="profile-name">${esc(name)}<small>${state.admin?'SUPERADMIN':'普通账号'}</small></span><button data-action="logout">退出</button></div></aside><main class="main"><header class="topbar"><div><div class="eyebrow">${state.admin&&state.owner?'账号数据 · '+esc(ownerName()):'SuirenX / Web 0.1.1'}</div><h1>${title}</h1></div><div class="top-actions"><span class="demo-tag">服务端数据</span><button class="btn mobile-menu" data-action="menu">☰</button>${state.admin&&['home','assets','expiry','conflicts'].includes(state.page)?workspaceSwitcher():''}</div></header>${sub?`<div class="notice" style="margin-bottom:16px">${sub}</div>`:''}${state.loadError?loadErrorNotice():''}${body}</main></div>`}
function ownerName(){return state.accounts.find(a=>a.id===state.owner)?.username||'管理员账户自身'}
function workspaceSwitcher(){const selected=state.accounts.find(a=>a.id===state.owner);const title=selected?.username||'管理员账户自身';return `<div class="workspace-switcher"><button class="workspace-trigger" type="button" data-action="toggle-workspaces" aria-haspopup="menu" aria-expanded="false"><span class="workspace-avatar">${esc(title.slice(0,1).toUpperCase())}</span><span class="workspace-current"><small>当前工作区</small><strong>${esc(title)}</strong></span><span class="workspace-chevron" aria-hidden="true">⌄</span></button><div class="workspace-menu" role="menu" aria-label="切换工作区"><div class="workspace-menu-label">我的工作区</div><button class="workspace-option ${state.owner?'':'selected'}" type="button" role="menuitemradio" aria-checked="${!state.owner}" data-action="workspace-owner" data-owner=""><span class="workspace-option-avatar">${esc((state.user||'S').slice(0,1).toUpperCase())}</span><span class="workspace-option-copy"><strong>管理员账户自身</strong><small>${esc(state.user||'超级管理员')}</small></span>${state.owner?'':'<span class="workspace-check" aria-hidden="true">✓</span>'}</button>${state.accounts.length?`<div class="workspace-menu-label workspace-other-label">其它账号</div>${state.accounts.map(a=>{const active=state.owner===a.id;return `<button class="workspace-option ${active?'selected':''}" type="button" role="menuitemradio" aria-checked="${active}" data-action="workspace-owner" data-owner="${esc(a.id)}" ${a.disabled_at?'disabled aria-disabled="true"':''}><span class="workspace-option-avatar">${esc((a.username||'A').slice(0,1).toUpperCase())}</span><span class="workspace-option-copy"><strong>${esc(a.username)}</strong><small>${a.disabled_at?'已停用 · 暂不可查看':'账号业务数据'}</small></span>${active?'<span class="workspace-check" aria-hidden="true">✓</span>':''}</button>`}).join('')}`:''}</div></div>`}
function login(){root.innerHTML=`<main class="login-wrap"><section class="login-story"><div class="brand"><span class="brand-mark">燧</span><span>燧人<small>SUIRENX · WEB</small></span></div><h1>把本机资产，<br>放在清楚的位置。</h1><p>Web 端用于跨设备查看与受控同步。资产、用品和配置的事实来源仍是本机；版本冲突会先展示差异，再由你明确选择。</p></section><section class="login-panel"><h2>进入 SuirenX</h2><p>使用已有账号登录工作区。</p><div class="login-switch"><button class="active" data-login-mode="user">普通账号</button><button data-login-mode="admin">超管</button></div><form id="login-form"><label class="form-field">账号<input class="field" name="username" autocomplete="username" required></label><label class="form-field">密码<input class="field" name="password" type="password" autocomplete="current-password" required></label><button class="btn primary" type="submit">登录</button><div id="login-error"></div></form><p style="margin-top:20px;font-size:11px">数据仅通过当前服务读取。超管账号由服务端环境配置。</p></section></main>`}
function loginMode(){return document.querySelector('[data-login-mode].active')?.dataset.loginMode||'user'}
async function loadAccounts(){if(!state.admin)return;state.accounts=(await api('/api/v1/admin/accounts')).accounts||[];if(state.owner&&!state.accounts.some(a=>a.id===state.owner)){state.owner='';sessionStorage.removeItem('sx_owner')}}
async function loadHome(){const [a,x]=await Promise.all([api('/api/v1/web/assets?scope=CURRENT'+(state.admin&&state.owner?`&owner_id=${encodeURIComponent(state.owner)}`:'')),api('/api/v1/web/expiry'+ownerQuery())]);state.assets=a.assets||[];state.expiry=x.items||[]}
function ownerQuery(){return state.admin&&state.owner?`?owner_id=${encodeURIComponent(state.owner)}`:''}
function metric(label,value,foot){return `<article class="metric"><div class="metric-label">${label}</div><div class="metric-value">${value}</div><div class="metric-foot">${foot}</div></article>`}
function home(){const active=state.assets.filter(a=>a.status==='ACTIVE');const total=state.assets.reduce((n,a)=>n+Number(a.price_cents||0),0);const daily=active.reduce((n,a)=>n+Number(a.daily_cost_cents||0),0);const pending=state.expiry.filter(x=>['EXPIRED','DUE_TODAY','SOON'].includes(expiryBucket(x))).length;frame('今天，从本机记录开始',`<div class="stack"><section class="metric-grid">${metric('未归档资产',state.assets.length,'当前账号 · 件')}${metric('购入金额合计',money(total),'记录金额 · 不代表估值')}${metric('服役中日均成本',money(daily),'按本机规则计算')}${metric('用品待处理',pending,'过期、今日到期或 7 天内临期')}</section><section class="two-col"><article class="card"><h2 class="card-title">继续处理 <small>当前账号数据</small></h2><div class="activity"><div class="activity-row"><i class="activity-dot"></i>资产记录<span>${state.assets.length} 项</span></div><div class="activity-row"><i class="activity-dot"></i>用品期限<span>${pending} 项待处理</span></div><div class="activity-row"><i class="activity-dot"></i>数据来源<span>服务器同步数据</span></div></div><div style="display:flex;gap:8px;margin-top:16px"><button class="btn primary" data-page="assets">打开资产列表</button><button class="btn" data-page="expiry">打开用品期限</button></div></article><article class="card"><h2 class="card-title">明确边界</h2><div class="boundary"><strong>本机事实来源</strong>Web 端可以查看、编辑并提交同步意图，不会绕过本机数据模型，也不会自动覆盖冲突版本。归档记录默认从总览与当前列表隐藏。<br><br>管理配置文件和受限 API token 仅对超管开放。</div></article></section></div>`)}
function statusBadge(a){return `<span class="status ${a.archived_at?'warn':a.status==='ACTIVE'?'active':'muted'}">${a.archived_at?'已归档':a.status==='ACTIVE'?'服役中':'已退役'}</span>`}
function assetRows(){const q=state.query.trim().toLowerCase();const items=state.assets.filter(a=>(state.assetStatus==='ALL'||a.status===state.assetStatus)&&(!q||`${a.name} ${a.purchase_channel} ${(a.tags||[]).join(' ')}`.toLowerCase().includes(q))).sort((a,b)=>{const x=a[state.assetSort],y=b[state.assetSort];return typeof x==='number'&&typeof y==='number'?y-x:String(y||'').localeCompare(String(x||''))});if(!items.length)return `<div class="empty"><strong>${q?'没有匹配记录':'这里还没有资产'}</strong>${q?'调整搜索词试试。':'新增一条记录，开始管理你的持有成本。'}</div>`;return `<div class="table-wrap"><table><thead><tr><th>名称</th><th>状态</th><th>购买日期</th><th>购入金额</th><th>日均成本</th><th>持有天数</th><th></th></tr></thead><tbody>${items.map(a=>`<tr><td><strong>${esc(a.name)}</strong><div class="subtext">${esc(a.purchase_channel||'资产记录')} · ${(a.tags||[]).map(esc).join('、')}</div></td><td>${statusBadge(a)}</td><td>${date(a.purchase_date)}</td><td>${money(a.price_cents)}</td><td>${money(a.daily_cost_cents)}</td><td>${a.held_days||0} 天</td><td><div class="row-actions">${a.archived_at?`<button class="btn small" data-action="restore-asset" data-id="${esc(a.id)}">恢复归档</button>`:`<button class="btn small" data-action="edit-asset" data-id="${esc(a.id)}">查看 / 编辑</button>`}<button class="btn small danger" data-action="delete-asset" data-id="${esc(a.id)}">删除</button></div></td></tr>`).join('')}</tbody></table></div>`}
function assets(){const body=`<section class="page-head"><div><h2>资产</h2><p>金额以整数分保存；归档与生命周期状态分开管理。</p></div><button class="btn primary" data-action="new-asset">＋ 新增资产</button></section><div class="toolbar"><input class="field" data-input="query" placeholder="搜索名称、购买渠道或标签" value="${esc(state.query)}"><select class="select" data-change="asset-scope"><option value="CURRENT" ${state.assetScope==='CURRENT'?'selected':''}>未归档</option><option value="ARCHIVED" ${state.assetScope==='ARCHIVED'?'selected':''}>已归档</option><option value="ALL" ${state.assetScope==='ALL'?'selected':''}>全部记录</option></select><select class="select" data-change="asset-status"><option value="ALL">全部状态</option><option value="ACTIVE" ${state.assetStatus==='ACTIVE'?'selected':''}>服役中</option><option value="RETIRED" ${state.assetStatus==='RETIRED'?'selected':''}>已退役</option></select><select class="select" data-change="asset-sort"><option value="purchase_date" ${state.assetSort==='purchase_date'?'selected':''}>按购买日期</option><option value="price_cents" ${state.assetSort==='price_cents'?'selected':''}>按购入金额</option><option value="daily_cost_cents" ${state.assetSort==='daily_cost_cents'?'selected':''}>按日均成本</option><option value="held_days" ${state.assetSort==='held_days'?'selected':''}>按持有天数</option><option value="name" ${state.assetSort==='name'?'selected':''}>按名称</option></select><button class="btn" data-action="refresh">刷新</button></div><article class="card">${assetRows()}</article>`;frame('资产',body,'已归档记录必须先恢复，再单独编辑；删除是独立操作，并保留同步 tombstone。')}
function actualExpiryDate(x){const dates=[x.package_expiry_date].filter(Boolean);if(x.opened_date&&Number(x.opened_validity_days)>0){const d=new Date(`${x.opened_date.slice(0,10)}T00:00:00Z`);d.setUTCDate(d.getUTCDate()+Number(x.opened_validity_days)-1);dates.push(d.toISOString().slice(0,10))}return dates.sort()[0]||''}
function dayDelta(dateValue){if(!dateValue)return null;const [y,m,d]=dateValue.slice(0,10).split('-').map(Number),now=new Date(),today=`${now.getFullYear()}-${String(now.getMonth()+1).padStart(2,'0')}-${String(now.getDate()).padStart(2,'0')}`,[ty,tm,td]=today.split('-').map(Number);return Math.round((Date.UTC(y,m-1,d)-Date.UTC(ty,tm-1,td))/86400000)}
function expiryBucket(x){if(x.archived_at||x.status!=='IN_USE')return 'INACTIVE';const days=dayDelta(actualExpiryDate(x));if(days===null)return 'NORMAL';if(days<0)return 'EXPIRED';if(days===0)return 'DUE_TODAY';if(days<=7)return 'SOON';return 'NORMAL'}
function expiryBucketLabel(x){const bucket=expiryBucket(x),days=dayDelta(actualExpiryDate(x));return ({EXPIRED:`已过期 ${Math.abs(days)} 天`,DUE_TODAY:'今日到期',SOON:`临期 · ${days} 天后`,NORMAL:`${days??'—'} 天后到期`,INACTIVE:x.archived_at?'已归档':'已处理'})[bucket]}
function expiryRows(){const q=state.query.trim().toLowerCase();const items=state.expiry.filter(x=>(state.expiryStatus==='ALL'||x.status===state.expiryStatus)&&(state.expiryBucket==='ALL'||expiryBucket(x)===state.expiryBucket)&&(!q||`${x.name} ${x.category} ${x.location}`.toLowerCase().includes(q))).sort((a,b)=>{const x=state.expirySort==='actual_expiry_date'?actualExpiryDate(a):a[state.expirySort],y=state.expirySort==='actual_expiry_date'?actualExpiryDate(b):b[state.expirySort];return String(x||'').localeCompare(String(y||''))});if(!items.length)return `<div class="empty"><strong>${q?'没有匹配用品':'这里还没有用品'}</strong>${q?'更换搜索词试试。':'添加用品期限以便查看保质期状态。'}</div>`;return `<div class="table-wrap"><table><thead><tr><th>用品</th><th>期限状态</th><th>使用状态</th><th>实际到期日</th><th>包装到期日</th><th>开封日期</th><th>开封有效期</th><th>位置</th><th></th></tr></thead><tbody>${items.map(x=>`<tr><td><strong>${esc(x.name)}</strong><div class="subtext">${esc(x.category||'用品')}</div></td><td><span class="status ${expiryBucket(x)==='EXPIRED'||expiryBucket(x)==='DUE_TODAY'?'danger':expiryBucket(x)==='SOON'||expiryBucket(x)==='INACTIVE'?'warn':'active'}">${esc(expiryBucketLabel(x))}</span></td><td><span class="status ${x.archived_at?'warn':x.status==='IN_USE'?'active':'muted'}">${x.archived_at?'已归档':expiryStatus(x.status)}</span></td><td>${date(actualExpiryDate(x))}</td><td>${date(x.package_expiry_date)}</td><td>${date(x.opened_date)}</td><td>${x.opened_validity_days?`${x.opened_validity_days} 天`:'—'}</td><td>${esc(x.location||'—')}</td><td><div class="row-actions">${x.archived_at?`<button class="btn small" data-action="restore-expiry" data-id="${esc(x.id)}">恢复归档</button>`:`<button class="btn small" data-action="edit-expiry" data-id="${esc(x.id)}">编辑</button>`}<button class="btn small danger" data-action="delete-expiry" data-id="${esc(x.id)}">删除</button></div></td></tr>`).join('')}</tbody></table></div>`}
function expiryStatus(s){return ({IN_USE:'使用中',USED_UP:'已用完',DISCARDED:'已丢弃'})[s]||s||'使用中'}
function expiry(){frame('用品期限',`<section class="page-head"><div><h2>用品期限</h2><p>实际到期日按包装期限与开封期限中较早者计算；Web 临期窗口为 7 天。位置为可选信息。</p></div><button class="btn primary" data-action="new-expiry">＋ 添加用品</button></section><div class="toolbar"><input class="field" data-input="query" placeholder="搜索名称、分类或位置" value="${esc(state.query)}"><select class="select" data-change="expiry-bucket"><option value="ALL">全部期限</option><option value="EXPIRED" ${state.expiryBucket==='EXPIRED'?'selected':''}>已过期</option><option value="DUE_TODAY" ${state.expiryBucket==='DUE_TODAY'?'selected':''}>今日到期</option><option value="SOON" ${state.expiryBucket==='SOON'?'selected':''}>7 天内临期</option><option value="NORMAL" ${state.expiryBucket==='NORMAL'?'selected':''}>正常</option><option value="INACTIVE" ${state.expiryBucket==='INACTIVE'?'selected':''}>已处理/归档</option></select><select class="select" data-change="expiry-status"><option value="ALL">全部使用状态</option><option value="IN_USE" ${state.expiryStatus==='IN_USE'?'selected':''}>使用中</option><option value="USED_UP" ${state.expiryStatus==='USED_UP'?'selected':''}>已用完</option><option value="DISCARDED" ${state.expiryStatus==='DISCARDED'?'selected':''}>已丢弃</option></select><select class="select" data-change="expiry-sort"><option value="actual_expiry_date" ${state.expirySort==='actual_expiry_date'?'selected':''}>按实际到期日</option><option value="name" ${state.expirySort==='name'?'selected':''}>按名称</option><option value="opened_date" ${state.expirySort==='opened_date'?'selected':''}>按开封日期</option></select><button class="btn" data-action="refresh">刷新</button></div><article class="card">${expiryRows()}</article>`,'此页面管理记录和日期，不提供库存数量或自动补货预测。')}
function modal(title,desc,content){const old=document.querySelector('.modal-backdrop');old?.remove();root.insertAdjacentHTML('beforeend',`<div class="modal-backdrop" data-action="backdrop"><section class="modal" role="dialog" aria-modal="true" aria-label="${esc(title)}"><header class="modal-header"><div><h2>${esc(title)}</h2><p>${esc(desc||'')}</p></div><button class="icon-btn" data-action="close-modal" aria-label="关闭">×</button></header>${content}</section></div>`)}
const val=(f,k)=>f.elements[k]?.value?.trim()||'';
function assetForm(a={}){const editing=!!a.id;modal(editing?'资产详情':'新增资产','保存将写入服务器同步事件，并由 Android 后续同步发现。',`<form id="asset-form" data-id="${esc(a.id||'')}" data-version="${esc(a.version||'')}"><input type="hidden" name="image_url" value="${esc(a.image_url||'')}"><input type="hidden" name="icon_key" value="${esc(a.icon_key||'')}"><div class="form-grid"><label class="form-field">名称<input class="field" name="name" required maxlength="200" value="${esc(a.name||'')}"></label><label class="form-field">购入金额（元）<input class="field" name="price" type="number" min="0" step="0.01" required value="${a.price_cents!=null?(Number(a.price_cents)/100).toFixed(2):''}"></label><label class="form-field">购买日期<input class="field" name="purchase_date" type="date" required value="${esc(a.purchase_date||'')}"></label><label class="form-field">购买渠道 / 分类<input class="field" name="purchase_channel" maxlength="120" value="${esc(a.purchase_channel||'')}"></label><label class="form-field">生命周期<select class="select" name="status"><option value="ACTIVE" ${a.status==='ACTIVE'?'selected':''}>服役中</option><option value="RETIRED" ${a.status==='RETIRED'?'selected':''}>已退役</option></select></label><label class="form-field">退役日期<input class="field" name="retired_date" type="date" value="${esc(a.retired_date||'')}"></label><label class="form-field">保修到期日<input class="field" name="warranty_end_date" type="date" value="${esc(a.warranty_end_date||'')}"></label><label class="form-field">标签（逗号分隔）<input class="field" name="tags" value="${esc((a.tags||[]).join(', '))}"></label><label class="form-field full">备注<textarea class="textarea" name="notes">${esc(a.notes||'')}</textarea></label><label class="form-field"><span>归档</span><select class="select" name="archived"><option value="false" ${!a.archived_at?'selected':''}>未归档</option><option value="true" ${a.archived_at?'selected':''}>已归档</option></select></label></div><div id="form-error"></div><div class="form-actions">${editing?`<button type="button" class="btn" data-action="toggle-retirement" data-id="${esc(a.id)}">${a.status==='ACTIVE'?'退役':'重新启用'}</button>`:''}<button type="button" class="btn" data-action="close-modal">取消</button><button class="btn primary" type="submit">保存记录</button></div></form>`)}
function expiryForm(x={}){const editing=!!x.id;modal(editing?'编辑用品':'添加用品','期限字段为 YYYY-MM-DD；位置可以留空。',`<form id="expiry-form" data-id="${esc(x.id||'')}" data-version="${esc(x.version||'')}"><div class="form-grid"><label class="form-field">名称<input class="field" name="name" required maxlength="200" value="${esc(x.name||'')}"></label><label class="form-field">分类<input class="field" name="category" maxlength="100" value="${esc(x.category||'')}"></label><label class="form-field">包装到期日<input class="field" name="package_expiry_date" type="date" value="${esc(x.package_expiry_date||'')}"></label><label class="form-field">开封日期<input class="field" name="opened_date" type="date" value="${esc(x.opened_date||'')}"></label><label class="form-field">开封后有效天数<input class="field" name="opened_validity_days" type="number" min="0" step="1" value="${Number(x.opened_validity_days||0)||''}"></label><label class="form-field">状态<select class="select" name="status"><option value="IN_USE" ${x.status==='IN_USE'||!x.status?'selected':''}>使用中</option><option value="USED_UP" ${x.status==='USED_UP'?'selected':''}>已用完</option><option value="DISCARDED" ${x.status==='DISCARDED'?'selected':''}>已丢弃</option></select></label><label class="form-field">位置（可选）<input class="field" name="location" value="${esc(x.location||'')}"></label><label class="form-field">归档<select class="select" name="archived"><option value="false" ${!x.archived_at?'selected':''}>未归档</option><option value="true" ${x.archived_at?'selected':''}>已归档</option></select></label><label class="form-field full">备注<textarea class="textarea" name="notes">${esc(x.notes||'')}</textarea></label></div><div id="form-error"></div><div class="form-actions"><button type="button" class="btn" data-action="close-modal">取消</button><button class="btn primary" type="submit">保存记录</button></div></form>`)}
async function conflicts(){frame('版本冲突',`<div class="stack"><article class="card"><h2 class="card-title">冲突处理</h2><div class="notice">版本冲突会在保存记录时即时返回。对比本次编辑与服务器最新版本后，你可以放弃本次修改，或明确选择以本次修改覆盖到最新版本。</div><div style="margin-top:14px"><button class="btn primary" data-action="open-assets">查看资产</button><button class="btn" data-action="open-expiry">查看用品</button></div></article><article class="card"><h2 class="card-title">当前可访问记录</h2><p class="muted" style="font-size:12px">服务器没有保存 Android 本地待处理冲突队列，因此这里不会虚构一份冲突列表。打开一条记录并保存时，服务器会检查 base_version。</p></article></div>`)}
function accountsPage(){const rows=state.accounts.map(a=>`<tr><td><strong>${esc(a.username)}</strong><div class="subtext">${esc(a.id)}</div></td><td>${esc(a.role)}</td><td><span class="status ${a.disabled_at?'danger':'active'}">${a.disabled_at?'已停用':'可登录'}</span></td><td>${date(a.created_at)}</td><td><div class="row-actions"><button class="btn small" data-action="account-data" data-id="${esc(a.id)}">查看业务数据</button>${a.username!==state.user?`<button class="btn small" data-action="toggle-account" data-id="${esc(a.id)}" data-disabled="${!a.disabled_at}">${a.disabled_at?'恢复账号':'停用账号'}</button>`:''}</div></td></tr>`).join('');frame('账号与数据',`<section class="page-head"><div><h2>账号管理</h2><p>停用后将阻止后续登录；已签发 JWT 按现有规则自然过期。</p></div><button class="btn" data-action="refresh">刷新</button></section><article class="card">${state.accounts.length?`<div class="table-wrap"><table><thead><tr><th>账号</th><th>角色</th><th>状态</th><th>创建时间</th><th>操作</th></tr></thead><tbody>${rows}</tbody></table></div>`:'<div class="empty">没有账号记录。</div>'}</article>`)}
function configsPage(){const rows=state.configs.map(c=>`<tr><td><strong>${esc(c.display_name)}</strong><div class="subtext">${esc(c.config_key)}</div></td><td>${c.deleted_at?'<span class="status danger">已删除</span>':'<span class="status active">可读取</span>'}</td><td>${date(c.updated_at)}</td><td><div class="row-actions"><button class="btn small" data-action="edit-config" data-id="${esc(c.config_key)}">编辑 / 查看原文</button>${!c.deleted_at?`<button class="btn small danger" data-action="delete-config" data-id="${esc(c.config_key)}">删除</button>`:''}</div></td></tr>`).join('');frame('配置文件',`<section class="page-head"><div><h2>通用文本配置</h2><p>按 UTF-8 原文保存，不解析格式；编辑会完整覆盖当前正文。</p></div><button class="btn primary" data-action="new-config">＋ 新建文件</button></section><article class="card">${state.configs.length?`<div class="table-wrap"><table><thead><tr><th>文件</th><th>状态</th><th>最近更新</th><th></th></tr></thead><tbody>${rows}</tbody></table></div>`:'<div class="empty"><strong>尚无配置文件</strong>创建后可以为读取 token 配置授权范围。</div>'}</article><div style="margin-top:14px"><button class="btn" data-action="config-limit">调整文件大小上限</button></div>`)}
function tokensPage(){const rows=state.tokens.map(t=>`<tr><td><strong>${esc(t.label)}</strong><div class="subtext">${esc(t.id)}</div></td><td>${esc(t.transport_mode)}</td><td>${(t.config_keys||[]).map(esc).join('<br>')}</td><td>${t.revoked_at?'<span class="status danger">已撤销</span>':t.expires_at&&new Date(t.expires_at)<new Date()?'<span class="status warn">已过期</span>':'<span class="status active">有效</span>'}</td><td>${date(t.created_at)}<div class="subtext">到期：${date(t.expires_at)}</div></td><td>${date(t.last_used_at)}</td><td>${!t.revoked_at?`<button class="btn small danger" data-action="revoke-token" data-id="${esc(t.id)}">撤销</button>`:'—'}</td></tr>`).join('');frame('API token',`<section class="page-head"><div><h2>受限读取凭据</h2><p>token 仅可读取授权配置；密钥只在签发时展示一次。</p></div><button class="btn primary" data-action="new-token">＋ 签发 token</button></section><article class="card">${state.tokens.length?`<div class="table-wrap"><table><thead><tr><th>名称</th><th>传递方式</th><th>授权配置</th><th>状态</th><th>签发 / 到期</th><th>最近使用</th><th></th></tr></thead><tbody>${rows}</tbody></table></div>`:'<div class="empty"><strong>尚无 API token</strong>为每个接入实例签发独立凭据。</div>'}</article><div class="notice" style="margin-top:14px">Query token 可能出现在基础设施 URL 日志中；启用前必须确认 HTTPS 与反向代理、WAF、APM 的 token 参数脱敏。</div>`)}
function pageKey(){return `${state.page}:${state.admin?(state.owner||state.user||'self'):'self'}`}
function loadErrorNotice(){return `<div class="notice error workspace-load-notice" role="alert"><strong>数据刷新失败</strong><p>${esc(state.loadError)} 当前已载入内容仍保留。</p><button class="btn small" type="button" data-action="retry-load">重试加载</button></div>`}
function renderLoading(){root.innerHTML='<main class="loading" role="status">正在载入工作区数据…</main>'}
function renderInitialLoadError(error){const message=error?.message||'请检查网络后重试。';frame('工作区暂不可用',`<section class="card workspace-load-error" role="alert"><h2>工作区数据未载入</h2><p>登录已成功，但首次工作区数据请求失败。当前登录会话仍然有效，请重试加载。</p><p class="muted">${esc(message)}</p><button class="btn primary" type="button" data-action="retry-load">重试加载</button></section>`)}
function render(){if(!state.token||state.page==='login'){login();state.renderedPageKey='';return}const titles={home:'今天，从本机记录开始',assets:'资产',expiry:'用品期限',conflicts:'版本冲突',accounts:'账号与数据',configs:'配置文件',tokens:'API token'};if(!titles[state.page]||(!state.admin&&['accounts','configs','tokens'].includes(state.page)))state.page='home';if(state.page==='home')home();else if(state.page==='assets')assets();else if(state.page==='expiry')expiry();else if(state.page==='conflicts')conflicts();else if(state.page==='accounts')accountsPage();else if(state.page==='configs')configsPage();else if(state.page==='tokens')tokensPage();state.renderedPageKey=pageKey()}
async function refresh(){if(!state.token){login();return}const key=pageKey();const preserve=state.loadedPages.has(key)&&state.renderedPageKey===key;state.loadError='';if(!preserve)renderLoading();else{const main=root.querySelector('.main');main?.setAttribute('aria-busy','true');if(main&&!main.querySelector('.workspace-refreshing'))main.querySelector('.topbar')?.insertAdjacentHTML('afterend','<div class="notice workspace-refreshing" role="status">正在刷新当前数据…</div>')}try{if(state.admin)await loadAccounts();if(state.page==='home')await loadHome();if(state.page==='assets'){const r=await api(`/api/v1/web/assets?scope=${state.assetScope}${ownerQuery()?`&owner_id=${encodeURIComponent(state.owner)}`:''}`);state.assets=r.assets||[]}if(state.page==='expiry')state.expiry=(await api('/api/v1/web/expiry'+ownerQuery())).items||[];if(state.page==='configs'){const [configs,registration]=await Promise.all([api('/api/v1/admin/configs'),api('/api/v1/admin/settings/account-registration')]);state.configs=configs.configs||[];state.accountRegistrationEnabled=registration.enabled}if(state.page==='tokens')state.tokens=(await api('/api/v1/admin/config-tokens')).tokens||[];state.loadedPages.add(pageKey());state.loadError='';render()}catch(e){root.querySelector('.workspace-refreshing')?.remove();root.querySelector('.main')?.removeAttribute('aria-busy');if(e.status===401){handleError(e);return}const message=e.message||'请检查网络后重试。';if(preserve){state.loadError=message;render()}else{state.loadError='';renderInitialLoadError(e)}}}
function handleError(e){if(e.status===401){logout();notify('登录状态已失效，请重新登录');return}notify(e.data?.code==='version_conflict'?'记录已在其他设备更新，请核对服务器版本。':e.message)}
function conflictForm(form,e,itemType,fd=new FormData(form)){if(e.status!==409||e.data?.code!=='version_conflict'||!e.data.remote){const box=form.querySelector('#form-error');if(box)box.innerHTML=`<div class="notice error" style="margin-top:12px">${esc(e.message)}</div>`;else notify(e.message);return}const remote=e.data.remote;const local=Object.fromEntries(fd);const localBody=itemType==='asset'?assetBody(form,fd):expiryBody(form,fd);modal('发现版本冲突','对比服务器最新内容后，再决定如何处理。',`<div class="conflict-cols"><section class="conflict-side"><h3>本次编辑 · 尚未提交</h3><pre class="token-secret">${esc(JSON.stringify(local,null,2))}</pre></section><section class="conflict-side"><h3>服务器版本 · v${esc(e.data.remote_version)}</h3><pre class="token-secret">${esc(JSON.stringify(remote,null,2))}</pre></section></div><div class="form-actions"><button class="btn" data-action="keep-remote">放弃本次修改，载入服务器版本</button><button class="btn primary" data-action="keep-local" data-type="${itemType}" data-id="${esc(form.dataset.id)}" data-remote-version="${esc(e.data.remote_version)}">保留本次修改，提交到新版本</button></div>`);state.pendingConflict={formData:local,type:itemType,id:form.dataset.id,body:localBody,remote,version:e.data.remote_version}}
function assetBody(form,fd=new FormData(form)){const retired=fd.get('status')==='RETIRED';const archived=fd.get('archived')==='true';return {name:val(form,'name'),price_cents:Math.round(Number(val(form,'price'))*100),purchase_date:val(form,'purchase_date'),status:val(form,'status'),retired_date:retired?(val(form,'retired_date')||new Date().toISOString().slice(0,10)):'',image_url:val(form,'image_url'),icon_key:val(form,'icon_key'),purchase_channel:val(form,'purchase_channel'),warranty_end_date:val(form,'warranty_end_date'),notes:val(form,'notes'),tags:val(form,'tags').split(',').map(s=>s.trim()).filter(Boolean),archived_at:archived?new Date().toISOString():''}}
function expiryBody(form,fd=new FormData(form)){return {name:val(form,'name'),category:val(form,'category'),package_expiry_date:val(form,'package_expiry_date'),opened_date:val(form,'opened_date'),opened_validity_days:Number(val(form,'opened_validity_days')||0),location:val(form,'location'),notes:val(form,'notes'),status:val(form,'status'),archived_at:fd.get('archived')==='true'?new Date().toISOString():''}}
function tokenBody(form,fd=new FormData(form)){return {label:val(form,'label'),transport_mode:val(form,'transport_mode'),config_keys:fd.getAll('config_keys'),expires_at:val(form,'expires_at')?new Date(val(form,'expires_at')).toISOString():''}}
async function saveAsset(form,baseVersion,body=assetBody(form),id=form.dataset.id){if(!id)await api('/api/v1/web/assets'+ownerQuery(),{method:'POST',headers:{'Idempotency-Key':key()},body});else await api(`/api/v1/web/assets/${encodeURIComponent(id)}${ownerQuery()}`,{method:'PUT',headers:{'Idempotency-Key':key()},body:{...body,base_version:Number(baseVersion)}});document.querySelector('.modal-backdrop')?.remove();notify('资产记录已保存');await refresh()}
async function saveExpiry(form,baseVersion,body=expiryBody(form),id=form.dataset.id){if(!id)await api('/api/v1/web/expiry'+ownerQuery(),{method:'POST',headers:{'Idempotency-Key':key()},body});else await api(`/api/v1/web/expiry/${encodeURIComponent(id)}${ownerQuery()}`,{method:'PUT',headers:{'Idempotency-Key':key()},body:{...body,base_version:Number(baseVersion)}});document.querySelector('.modal-backdrop')?.remove();notify('用品记录已保存');await refresh()}
async function startLogin(form){const mode=loginMode(),err=document.querySelector('#login-error');err.innerHTML='';let data;try{data=await api(mode==='admin'?'/api/v1/admin/auth/login':'/api/v1/auth/login',{method:'POST',body:{username:val(form,'username'),password:val(form,'password')}})}catch(e){err.innerHTML=`<div class="notice error">${esc(e.message)}${e.data?.code==='admin_login_unavailable'?' · 检查服务端超管环境配置。':''}</div>`;return}state.token=data.access_token;state.user=val(form,'username');state.admin=mode==='admin';state.loadError='';state.loadedPages.clear();state.renderedPageKey='';sessionStorage.setItem('sx_token',state.token);sessionStorage.setItem('sx_user',state.user);sessionStorage.setItem('sx_admin',String(state.admin));state.page='home';location.hash='home';await refresh()}
async function openAsset(id){try{const a=await api(`/api/v1/web/assets/${encodeURIComponent(id)}${ownerQuery()}`);assetForm(a)}catch(e){handleError(e)}}
async function openExpiry(id){const x=state.expiry.find(i=>i.id===id);if(x)expiryForm(x)}
async function deleteRecord(type,id){const rows=type==='asset'?state.assets:state.expiry;const item=rows.find(x=>x.id===id);if(!item||!confirm(`永久删除“${item.name}”？此操作独立于归档，并会保留同步 tombstone。`))return;try{await api(`/api/v1/web/${type==='asset'?'assets':'expiry'}/${encodeURIComponent(id)}${ownerQuery()}`,{method:'DELETE',headers:{'Idempotency-Key':key()},body:{base_version:item.version}});notify('已删除并保留同步 tombstone');await refresh()}catch(e){if(e.status===409&&e.data?.remote){modal('记录版本已改变','核对服务器最新快照，再明确选择保留服务器版本或确认删除新版本。',`<div class="conflict-cols"><section class="conflict-side"><h3>准备删除</h3><p>${esc(item.name)}</p></section><section class="conflict-side"><h3>服务器版本 · v${esc(e.data.remote_version)}</h3><pre class="token-secret">${esc(JSON.stringify(e.data.remote,null,2))}</pre></section></div><div class="form-actions"><button class="btn" data-action="cancel-conflict-delete">保留服务器版本</button><button class="btn danger" data-action="confirm-conflict-delete" data-type="${type}" data-id="${esc(id)}" data-version="${esc(e.data.remote_version)}">确认删除服务器版本</button></div>`);state.pendingDelete={type,id,version:e.data.remote_version}}else handleError(e)}}
async function restoreArchived(type,id){const item=(type==='asset'?state.assets:state.expiry).find(x=>x.id===id);if(!item)return;const route=type==='asset'?'assets':'expiry';const body=type==='asset'?{name:item.name,price_cents:item.price_cents,purchase_date:item.purchase_date,status:item.status,retired_date:item.retired_date||'',image_url:item.image_url||'',icon_key:item.icon_key||'',purchase_channel:item.purchase_channel||'',warranty_end_date:item.warranty_end_date||'',notes:item.notes||'',tags:item.tags||[],archived_at:''}:{name:item.name,category:item.category||'',package_expiry_date:item.package_expiry_date||'',opened_date:item.opened_date||'',opened_validity_days:item.opened_validity_days||0,location:item.location||'',notes:item.notes||'',status:item.status,archived_at:''};try{await api(`/api/v1/web/${route}/${encodeURIComponent(id)}${ownerQuery()}`,{method:'PUT',headers:{'Idempotency-Key':key()},body:{...body,base_version:item.version}});notify('记录已恢复，可继续编辑');await refresh()}catch(e){handleError(e)}}
async function toggleRetirement(id){const a=await api(`/api/v1/web/assets/${encodeURIComponent(id)}${ownerQuery()}`);const active=a.status!=='ACTIVE';const body={base_version:a.version,name:a.name,price_cents:a.price_cents,purchase_date:a.purchase_date,status:active?'ACTIVE':'RETIRED',retired_date:active?'':new Date().toISOString().slice(0,10),archived_at:a.archived_at||'',image_url:a.image_url||'',icon_key:a.icon_key||'',purchase_channel:a.purchase_channel||'',warranty_end_date:a.warranty_end_date||'',notes:a.notes||'',tags:a.tags||[]};try{await api(`/api/v1/web/assets/${encodeURIComponent(id)}${ownerQuery()}`,{method:'PUT',headers:{'Idempotency-Key':key()},body});document.querySelector('.modal-backdrop')?.remove();notify(active?'已重新启用':'已退役');await refresh()}catch(e){handleError(e)}}
async function fetchConfig(key){return api(`/api/v1/admin/configs/${encodeURIComponent(key)}`)}
function configForm(c={}){modal(c.config_key?'编辑配置文件':'新建配置文件','UTF-8 文本原文，不解析格式；保存将完整覆盖正文。',`<form id="config-form" data-key="${esc(c.config_key||'')}"><div class="form-grid"><label class="form-field full">显示名称<input class="field" name="display_name" required maxlength="120" value="${esc(c.display_name||'')}"></label><label class="form-field full">配置正文<textarea class="textarea" style="min-height:320px;font-family:ui-monospace,monospace" name="content" spellcheck="false">${esc(c.content||'')}</textarea></label></div><div id="form-error"></div><div class="form-actions"><button type="button" class="btn" data-action="close-modal">取消</button><button class="btn primary" type="submit">保存完整正文</button></div></form>`)}
function tokenForm(){modal('签发 API token','密钥仅显示一次。请选择本实例允许读取的配置和传递方式。',`<form id="token-form"><div class="form-grid"><label class="form-field full">名称<input class="field" name="label" required maxlength="100" placeholder="例如 Mihomo · NAS"></label><label class="form-field">传递方式<select class="select" name="transport_mode"><option value="BEARER">Authorization: Bearer</option><option value="QUERY">Query 参数（需基础设施脱敏）</option></select></label><label class="form-field">到期日（可选）<input class="field" name="expires_at" type="datetime-local"></label><fieldset class="form-field full" style="border:1px solid var(--line);border-radius:10px;padding:12px"><legend>允许读取的配置</legend>${state.configs.filter(c=>!c.deleted_at).map(c=>`<label style="display:block;margin:7px 0"><input type="checkbox" name="config_keys" value="${esc(c.config_key)}"> ${esc(c.display_name)} <small class="muted">${esc(c.config_key)}</small></label>`).join('')||'<span class="muted">请先创建配置文件。</span>'}</fieldset></div><div id="form-error"></div><div class="form-actions"><button type="button" class="btn" data-action="close-modal">取消</button><button class="btn primary" type="submit">签发并展示密钥</button></div></form>`)}
async function showIssuedToken(t){state.tokens=(await api('/api/v1/admin/config-tokens')).tokens||[];tokensPage();modal('请立即复制 token','出于安全考虑，此密钥不会再次显示。妥善保存在目标客户端中。',`<div class="token-secret" id="issued-token">${esc(t.token)}</div><p style="margin-top:12px;font-size:12px">授权配置：${(t.config_keys||[]).map(esc).join('、')||'—'}</p><div class="form-actions"><button class="btn primary" data-action="copy-token">复制 token</button><button class="btn" data-action="close-modal">我已保存</button></div>`)}
root.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.page){state.page=b.dataset.page;state.query='';location.hash=state.page;await refresh();return}const act=b.dataset.action;try{if(act==='logout')logout();else if(act==='menu')root.querySelector('.shell')?.classList.toggle('menu-open');else if(act==='toggle-workspaces'){const wrap=b.closest('.workspace-switcher');const open=wrap.classList.toggle('open');b.setAttribute('aria-expanded',String(open))}else if(act==='workspace-owner'){state.owner=b.dataset.owner||'';if(state.owner)sessionStorage.setItem('sx_owner',state.owner);else sessionStorage.removeItem('sx_owner');await refresh()}else if(act==='refresh'||act==='retry-load')await refresh();else if(act==='new-asset')assetForm();else if(act==='edit-asset')await openAsset(b.dataset.id);else if(act==='delete-asset')await deleteRecord('asset',b.dataset.id);else if(act==='restore-asset')await restoreArchived('asset',b.dataset.id);else if(act==='new-expiry')expiryForm();else if(act==='edit-expiry')openExpiry(b.dataset.id);else if(act==='delete-expiry')await deleteRecord('expiry',b.dataset.id);else if(act==='restore-expiry')await restoreArchived('expiry',b.dataset.id);else if(act==='open-assets'){state.page='assets';location.hash='assets';await refresh()}else if(act==='open-expiry'){state.page='expiry';location.hash='expiry';await refresh()}else if(act==='close-modal'||(act==='backdrop'&&e.target===b))document.querySelector('.modal-backdrop')?.remove();else if(act==='toggle-retirement')await toggleRetirement(b.dataset.id);else if(act==='keep-remote'){const p=state.pendingConflict;document.querySelector('.modal-backdrop')?.remove();if(p){state.pendingConflict=null;if(p.type==='asset')await openAsset(p.id);else await openExpiry(p.id)}}else if(act==='keep-local'){const p=state.pendingConflict;if(!p)return;state.pendingConflict=null;document.querySelector('.modal-backdrop')?.remove();if(p.type==='asset')await saveAsset(null,p.version,p.body,p.id);else await saveExpiry(null,p.version,p.body,p.id)}else if(act==='cancel-conflict-delete'){state.pendingDelete=null;document.querySelector('.modal-backdrop')?.remove()}else if(act==='confirm-conflict-delete'){const p=state.pendingDelete;if(!p)return;state.pendingDelete=null;document.querySelector('.modal-backdrop')?.remove();await api(`/api/v1/web/${p.type==='asset'?'assets':'expiry'}/${encodeURIComponent(p.id)}${ownerQuery()}`,{method:'DELETE',headers:{'Idempotency-Key':key()},body:{base_version:Number(p.version)}});notify('已删除并保留同步 tombstone');await refresh()}else if(act==='account-data'){state.owner=b.dataset.id;sessionStorage.setItem('sx_owner',state.owner);state.page='assets';location.hash='assets';await refresh()}else if(act==='toggle-account'){const disabled=b.dataset.disabled==='true';if(!confirm(`${disabled?'停用':'恢复'}此账号？`))return;await api(`/api/v1/admin/accounts/${encodeURIComponent(b.dataset.id)}/status`,{method:'PATCH',body:{disabled}});notify(disabled?'账号已停用':'账号已恢复');await refresh()}else if(act==='new-config')configForm();else if(act==='edit-config')configForm(await fetchConfig(b.dataset.id));else if(act==='delete-config'){if(confirm('删除此配置文件？已授权 token 将保留，但无法读取已删除的 key。')){await api(`/api/v1/admin/configs/${encodeURIComponent(b.dataset.id)}`,{method:'DELETE'});notify('配置已删除');await refresh()}}else if(act==='config-limit'){const d=await api('/api/v1/admin/settings/config-max-bytes');const raw=prompt('配置正文最大字节数（1 至 104857600）',d.max_bytes);if(raw!==null){await api('/api/v1/admin/settings/config-max-bytes',{method:'PUT',body:{max_bytes:Number(raw)}});notify('文件大小上限已更新')}}else if(act==='new-token'){await refreshConfigsForToken()}else if(act==='revoke-token'){if(confirm('撤销此 token？撤销后授权读取立即拒绝。')){await api(`/api/v1/admin/config-tokens/${encodeURIComponent(b.dataset.id)}`,{method:'DELETE'});notify('token 已撤销');await refresh()}}else if(act==='copy-token'){await navigator.clipboard.writeText(document.querySelector('#issued-token').textContent);notify('已复制，请保存到目标客户端')} }catch(err){handleError(err)}});
async function refreshConfigsForToken(){state.configs=(await api('/api/v1/admin/configs')).configs||[];tokenForm()}
root.addEventListener('change',async e=>{if(e.target.dataset.change==='asset-scope'){state.assetScope=e.target.value;await refresh()}if(e.target.dataset.change==='asset-status'){state.assetStatus=e.target.value;assets()}if(e.target.dataset.change==='asset-sort'){state.assetSort=e.target.value;assets()}if(e.target.dataset.change==='expiry-status'){state.expiryStatus=e.target.value;expiry()}if(e.target.dataset.change==='expiry-bucket'){state.expiryBucket=e.target.value;expiry()}if(e.target.dataset.change==='expiry-sort'){state.expirySort=e.target.value;expiry()}});
root.addEventListener('input',e=>{if(e.target.dataset.input==='query'){state.query=e.target.value;if(state.page==='assets')assets();else if(state.page==='expiry')expiry();const input=root.querySelector('[data-input="query"]');input?.focus();input?.setSelectionRange(state.query.length,state.query.length)}});
document.addEventListener('click',e=>{if(!e.target.closest('.workspace-switcher')){const wrap=root.querySelector('.workspace-switcher.open');wrap?.classList.remove('open');wrap?.querySelector('[data-action="toggle-workspaces"]')?.setAttribute('aria-expanded','false')}});document.addEventListener('keydown',e=>{if(e.key==='Escape'){const wrap=root.querySelector('.workspace-switcher.open');if(wrap){wrap.classList.remove('open');wrap.querySelector('[data-action="toggle-workspaces"]')?.setAttribute('aria-expanded','false')}}});
const pendingFormState=new WeakMap();
function setFormPending(form,pending){if(!form?.isConnected)return;if(pending){if(form.dataset.pending==='true')return;const container=form.closest('.modal')||form;const controls=[...new Set(container.querySelectorAll('button,input,select,textarea'))];if(form.id==='login-form')controls.push(...document.querySelectorAll('[data-login-mode]'));const submit=form.querySelector('button[type="submit"]');pendingFormState.set(form,{controls:controls.map(control=>[control,control.disabled]),submit,label:submit?.textContent||''});form.dataset.pending='true';form.setAttribute('aria-busy','true');for(const control of controls)control.disabled=true;if(submit)submit.textContent=form.id==='login-form'?'正在登录…':form.id==='token-form'?'正在签发…':'正在保存…';return}const prior=pendingFormState.get(form);if(!prior)return;delete form.dataset.pending;form.removeAttribute('aria-busy');for(const [control,disabled] of prior.controls)if(control.isConnected)control.disabled=disabled;if(prior.submit?.isConnected)prior.submit.textContent=prior.label;pendingFormState.delete(form)}
root.addEventListener('submit',async e=>{const f=e.target;if(!['login-form','asset-form','expiry-form','config-form','token-form'].includes(f.id))return;e.preventDefault();if(f.dataset.pending==='true')return;const fd=new FormData(f);if(f.id==='token-form'&&!fd.getAll('config_keys').length){const box=f.querySelector('#form-error');if(box)box.innerHTML='<div class="notice error" style="margin-top:12px">至少选择一个配置文件</div>';return}const payload=f.id==='asset-form'?assetBody(f,fd):f.id==='expiry-form'?expiryBody(f,fd):f.id==='token-form'?tokenBody(f,fd):null;setFormPending(f,true);try{if(f.id==='login-form'){await startLogin(f);return}if(f.id==='asset-form'){await saveAsset(f,Number(f.dataset.version),payload);return}if(f.id==='expiry-form'){await saveExpiry(f,Number(f.dataset.version),payload);return}if(f.id==='config-form'){const k=f.dataset.key;const body={display_name:val(f,'display_name'),content:val(f,'content')};await api(k?`/api/v1/admin/configs/${encodeURIComponent(k)}`:'/api/v1/admin/configs',{method:k?'PUT':'POST',body});document.querySelector('.modal-backdrop')?.remove();notify('配置文件已保存');await refresh();return}if(f.id==='token-form'){const token=await api('/api/v1/admin/config-tokens',{method:'POST',body:payload});await showIssuedToken(token);return}}catch(err){if((f.id==='asset-form'||f.id==='expiry-form')&&err.status===409){conflictForm(f,err,f.id==='asset-form'?'asset':'expiry',fd);return}const box=f.querySelector('#form-error')||f.querySelector('#login-error');if(box)box.innerHTML=`<div class="notice error" style="margin-top:12px">${esc(err.message)}</div>`;else handleError(err)}finally{setFormPending(f,false)}});
root.addEventListener('click',e=>{const b=e.target.closest('[data-login-mode]');if(b){document.querySelectorAll('[data-login-mode]').forEach(x=>x.classList.toggle('active',x===b))}});
window.addEventListener('hashchange',()=>{const p=location.hash.slice(1)||'home';if(p==='login'){logout();return}state.page=p;refresh()});

function configReadPath(configKey){return '/api/v1/configs/'+encodeURIComponent(configKey)+'/content'}
function configsPage(){
  const rows=state.configs.map(c=>{
    const readPath=c.deleted_at?'<span class="subtext">已删除 · 不可读取</span>':'<div class="config-read-path">GET '+esc(configReadPath(c.config_key))+'</div><button class="btn small" data-action="copy-config-path" data-path="'+esc(configReadPath(c.config_key))+'">复制路径</button>';
    return '<tr><td><strong>'+esc(c.display_name)+'</strong><div class="subtext">'+esc(c.config_key)+'</div>'+readPath+'</td><td>'+(c.deleted_at?'<span class="status danger">已删除</span>':'<span class="status active">可读取</span>')+'</td><td>'+date(c.updated_at)+'</td><td><div class="row-actions"><button class="btn small" data-action="edit-config" data-id="'+esc(c.config_key)+'">编辑 / 查看原文</button>'+(c.deleted_at?'':'<button class="btn small danger" data-action="delete-config" data-id="'+esc(c.config_key)+'">删除</button>')+'</div></td></tr>'
  }).join('');
  const enabled=state.accountRegistrationEnabled===true;
  frame('配置文件','<section class="page-head"><div><h2>配置文件</h2><p>按 UTF-8 原文保存，不解析格式；读取地址只展示 path，不包含服务器域名。</p></div><button class="btn primary" data-action="new-config">＋ 新建文件</button></section><section class="card server-setting-card"><div><h2 class="card-title">服务器配置</h2><strong>允许新账号注册</strong><p class="subtext">'+(enabled?'开启后，新的账号可从 App 注册。':'关闭后，App 新注册请求会被拒绝；已有账号仍可登录。')+'</p></div><button type="button" class="registration-switch" role="switch" aria-checked="'+(enabled?'true':'false')+'" data-action="toggle-registration"><span class="registration-track"><span></span></span><span>'+(enabled?'已开启':'已关闭')+'</span></button></section><article class="card">'+(state.configs.length?'<div class="table-wrap"><table><thead><tr><th>文件与读取路径</th><th>状态</th><th>最近更新</th><th></th></tr></thead><tbody>'+rows+'</tbody></table></div>':'<div class="empty"><strong>尚无配置文件</strong>创建后可以为读取 token 配置授权范围。</div>')+'</article><div class="config-page-actions"><button class="btn" data-action="config-limit">调整文件大小上限</button></div>')
}
function tokensPage(){
  const rows=state.tokens.map(t=>{
    const revoked=!!t.revoked_at;
    const expired=!revoked&&t.expires_at&&new Date(t.expires_at)<new Date();
    const actions=revoked?'—':'<button class="btn small" data-action="edit-token" data-id="'+esc(t.id)+'">编辑</button><button class="btn small danger" data-action="revoke-token" data-id="'+esc(t.id)+'">撤销</button>';
    return '<tr><td><strong>'+esc(t.label)+'</strong><div class="subtext">'+esc(t.id)+'</div></td><td>'+esc(t.transport_mode)+'</td><td>'+(t.config_keys||[]).map(esc).join('<br>')+'</td><td>'+(revoked?'<span class="status danger">已撤销</span>':expired?'<span class="status warn">已过期</span>':'<span class="status active">有效</span>')+'</td><td>'+date(t.created_at)+'<div class="subtext">到期：'+date(t.expires_at)+'</div></td><td>'+date(t.last_used_at)+'</td><td><div class="row-actions">'+actions+'</div></td></tr>'
  }).join('');
  frame('API token','<section class="page-head"><div><h2>受限读取凭据</h2><p>token 仅可读取授权配置；密钥只在签发时展示一次。</p></div><button class="btn primary" data-action="new-token">＋ 签发 token</button></section><article class="card">'+(state.tokens.length?'<div class="table-wrap"><table class="token-table"><thead><tr><th>名称</th><th>传递方式</th><th>授权配置</th><th>状态</th><th>签发 / 到期</th><th>最近使用</th><th></th></tr></thead><tbody>'+rows+'</tbody></table></div>':'<div class="empty"><strong>尚无 API token</strong>为每个接入实例签发独立凭据。</div>')+'</article><div class="notice" style="margin-top:14px">Query token 可能出现在基础设施 URL 日志中；启用前必须确认 HTTPS 与反向代理、WAF、APM 的 token 参数脱敏。</div>')
}
function tokenEditForm(token){
  if(!token||token.revoked_at){notify('已撤销的 token 不可编辑');return}
  const allowed=new Set(token.config_keys||[]);
  const configs=state.configs.filter(c=>!c.deleted_at);
  modal('编辑 API token','可同时修改名称与授权配置。密钥、传递方式和有效期保持不变。', '<form id="token-edit-form" data-id="'+esc(token.id)+'"><div class="form-grid"><label class="form-field full">名称<input class="field" name="label" required maxlength="100" value="'+esc(token.label)+'"></label><fieldset class="form-field full" style="border:1px solid var(--line);border-radius:10px;padding:12px"><legend>允许读取的配置（至少一项）</legend>'+(configs.map(c=>'<label class="token-config-option"><input type="checkbox" name="config_keys" value="'+esc(c.config_key)+'" '+(allowed.has(c.config_key)?'checked':'')+'> '+esc(c.display_name)+' <small class="muted">'+esc(c.config_key)+'</small></label>').join('')||'<span class="muted">没有可授权的配置文件。</span>')+'</fieldset><div class="notice full">此次编辑不会显示或重新生成密钥。</div></div><div id="form-error"></div><div class="form-actions"><button type="button" class="btn" data-action="close-modal">取消</button><button class="btn primary" type="submit">保存名称与授权</button></div></form>')
}
root.addEventListener('click',async e=>{
  const b=e.target.closest('button[data-action]');if(!b)return;
  try{
    if(b.dataset.action==='copy-config-path'){
      const path=b.dataset.path;
      try{await navigator.clipboard.writeText(path);notify('读取路径已复制')}catch(_){notify('无法访问剪贴板，请手动复制页面中的读取路径')}
    }else if(b.dataset.action==='toggle-registration'){
      const result=await api('/api/v1/admin/settings/account-registration',{method:'PUT',body:{enabled:!state.accountRegistrationEnabled}});
      state.accountRegistrationEnabled=result.enabled;render();notify(result.enabled?'已允许新账号注册':'已关闭新账号注册，已有账号仍可登录')
    }else if(b.dataset.action==='edit-token'){
      state.configs=(await api('/api/v1/admin/configs')).configs||[];
      tokenEditForm(state.tokens.find(t=>t.id===b.dataset.id))
    }
  }catch(err){handleError(err)}
});
root.addEventListener('submit',async e=>{
  const f=e.target;if(f.id!=='token-edit-form')return;e.preventDefault();
  if(f.dataset.pending==='true')return;
  const formData=new FormData(f);
  const keys=Array.from(formData.getAll('config_keys'));
  const label=formData.get('label')?.trim()||'';
  const box=f.querySelector('#form-error');
  if(!label||!keys.length){if(box)box.innerHTML='<div class="notice error" style="margin-top:12px">'+esc(!label?'名称不能为空。':'至少选择一个授权配置。')+'</div>';return}
  setFormPending(f,true);try{
    await api('/api/v1/admin/config-tokens/'+encodeURIComponent(f.dataset.id),{method:'PUT',body:{label,config_keys:keys}});
    document.querySelector('.modal-backdrop')?.remove();notify('token 名称与授权范围已更新');await refresh()
  }catch(err){if(box)box.innerHTML='<div class="notice error" style="margin-top:12px">'+esc(err.message)+'</div>';else handleError(err)}finally{setFormPending(f,false)}
});

(async()=>{if(state.token){await refresh()}else{state.page='login';login()}})();
